package message

import (
	"fmt"
	"net/http"
	"strings"

	"github.com/ai-agent-os/ai-agent-os/dto"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/app"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/response"
)

type SendReq struct {
	ToUsers       string `json:"to_users" widget:"name:接收用户;type:users"`
	ToDepartments string `json:"to_departments" widget:"name:接收部门;type:departments"`
	Title         string `json:"title" widget:"name:消息标题;type:input;placeholder:可选，不填由消息服务使用默认标题"`
	Content       string `json:"content" widget:"name:消息内容;type:text_area;rows:8" validate:"required,min=1"`
	ContentType   string `json:"content_type" widget:"name:内容类型;type:select;options:markdown,html,text;render_default:markdown"`
}

type SendResp struct {
	Message       string `json:"message" widget:"name:消息;type:text_area"`
	From          string `json:"from" widget:"name:发送人;type:input"`
	FullCodePath  string `json:"full_code_path" widget:"name:来源路径;type:input"`
	ToUsers       string `json:"to_users" widget:"name:接收用户;type:users"`
	ToDepartments string `json:"to_departments" widget:"name:接收部门;type:departments"`
	ContentType   string `json:"content_type" widget:"name:内容类型;type:input"`
	Summary       string `json:"summary" widget:"name:发送结果;type:text_area"`
}

func Send(ctx *app.Context, resp response.Response) error {
	var req SendReq
	if err := ctx.ShouldBindValidate(&req); err != nil {
		return err
	}
	if strings.TrimSpace(req.ToUsers) == "" && strings.TrimSpace(req.ToDepartments) == "" {
		return fmt.Errorf("to_users 和 to_departments 至少填写一个")
	}
	contentType := strings.TrimSpace(req.ContentType)
	if contentType == "" {
		contentType = "markdown"
	}

	apiReq := &dto.MessageSendEnvelope{
		Meta: dto.MessageSendMeta{
			FullCodePath: strings.TrimSpace(ctx.GetFullCodePath()),
		},
		Message: dto.MessageSendPayload{
			ToUsers:       strings.TrimSpace(req.ToUsers),
			ToDepartments: strings.TrimSpace(req.ToDepartments),
			Title:         strings.TrimSpace(req.Title),
			Content:       strings.TrimSpace(req.Content),
			ContentType:   contentType,
		},
	}
	var result dto.MessageSendResp
	if err := ctx.APICall(http.MethodPost, "/message/api/v1/send", apiReq, &result); err != nil {
		return fmt.Errorf("[系统错误]-[MessageSend] 发送消息失败, req: %+v, err: %w", req, err)
	}

	return resp.Form(&SendResp{
		Message:       result.Message,
		From:          result.From,
		FullCodePath:  result.FullCodePath,
		ToUsers:       result.ToUsers,
		ToDepartments: result.ToDepartments,
		ContentType:   result.ContentType,
		Summary:       formatSendSummary(&result),
	}).Build()
}

var SendTemplate = &app.FormTemplate{
	BaseConfig: app.BaseConfig{
		Name:     "发送消息通知",
		Desc:     "通过 message-server 向指定用户和/或部门发送消息通知。支持 markdown、html、text 内容类型。会产生副作用，执行前必须确认接收人和内容。",
		Tags:     []string{"消息通知", "发送", "平台接口", "副作用"},
		Request:  &SendReq{},
		Response: &SendResp{},
	},
}

func init() {
	packageContext.POST("send.form", Send, SendTemplate)
}

func formatSendSummary(result *dto.MessageSendResp) string {
	if result == nil {
		return "消息已提交发送。"
	}
	lines := []string{
		"消息已提交发送。",
		"内容类型: " + result.ContentType,
	}
	if result.ToUsers != "" {
		lines = append(lines, "接收用户: "+result.ToUsers)
	}
	if result.ToDepartments != "" {
		lines = append(lines, "接收部门: "+result.ToDepartments)
	}
	if result.From != "" {
		lines = append(lines, "发送人: "+result.From)
	}
	if result.FullCodePath != "" {
		lines = append(lines, "来源路径: "+result.FullCodePath)
	}
	return strings.Join(lines, "\n")
}

