package operate_log

import (
	"fmt"
	"net/http"
	"net/url"
	"strconv"
	"strings"

	"github.com/ai-agent-os/ai-agent-os/dto"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/app"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/response"
)

type FormReq struct {
	TenantUser   string `json:"tenant_user" widget:"name:租户用户;type:input"`
	RequestUser  string `json:"request_user" widget:"name:请求用户;type:input"`
	App          string `json:"app" widget:"name:应用;type:input"`
	FullCodePath string `json:"full_code_path" widget:"name:完整路径;type:input"`
	Action       string `json:"action" widget:"name:操作类型;type:select;options:,request_app,form_submit"`
	Source       string `json:"source" widget:"name:来源;type:select;options:,browser,scheduled_task,agent,api"`
	Status       string `json:"status" widget:"name:状态;type:select;options:,success,failed"`
	TraceID      string `json:"trace_id" widget:"name:Trace ID;type:input"`
	Keyword      string `json:"keyword" widget:"name:关键词;type:input"`
	Page         int    `json:"page" widget:"name:页码;type:number;min:1;render_default:1"`
	PageSize     int    `json:"page_size" widget:"name:每页数量;type:number;min:1;max:100;render_default:20"`
	OrderBy      string `json:"order_by" widget:"name:排序;type:input;placeholder:默认 created_at DESC"`
}

type FormResp struct {
	Total    int64  `json:"total" widget:"name:总数;type:number"`
	Page     int    `json:"page" widget:"name:页码;type:number"`
	PageSize int    `json:"page_size" widget:"name:每页数量;type:number"`
	LogsJSON string `json:"logs_json" widget:"name:日志 JSON;type:text_area"`
}

func Form(ctx *app.Context, resp response.Response) error {
	var req FormReq
	if err := ctx.ShouldBindValidate(&req); err != nil {
		return err
	}
	query := url.Values{}
	setQueryIfNotEmpty(query, "tenant_user", req.TenantUser)
	setQueryIfNotEmpty(query, "request_user", req.RequestUser)
	setQueryIfNotEmpty(query, "app", req.App)
	setQueryIfNotEmpty(query, "full_code_path", req.FullCodePath)
	setQueryIfNotEmpty(query, "action", req.Action)
	setQueryIfNotEmpty(query, "source", req.Source)
	setQueryIfNotEmpty(query, "status", req.Status)
	setQueryIfNotEmpty(query, "trace_id", req.TraceID)
	setQueryIfNotEmpty(query, "keyword", req.Keyword)
	setQueryIfNotEmpty(query, "order_by", req.OrderBy)
	query.Set("page", strconv.Itoa(normalizePositive(req.Page, 1)))
	query.Set("page_size", strconv.Itoa(normalizeRange(req.PageSize, 20, 1, 100)))

	var result dto.GetFormOperateLogsResp
	if err := ctx.APICall(http.MethodGet, "/workspace/api/v1/operate_log/form?"+query.Encode(), nil, &result); err != nil {
		return fmt.Errorf("[系统错误]-[OperateLogForm] 查询表单操作日志失败, req: %+v, err: %w", req, err)
	}
	logsJSON, err := marshalPretty(result.Logs)
	if err != nil {
		return err
	}
	return resp.Form(&FormResp{
		Total:    result.Total,
		Page:     result.Page,
		PageSize: result.PageSize,
		LogsJSON: strings.TrimSpace(logsJSON),
	}).Build()
}

var FormTemplate = &app.FormTemplate{
	BaseConfig: app.BaseConfig{
		Name:     "查询表单操作日志",
		Desc:     "查询 Form 请求和提交操作日志。只读接口，受平台权限和企业版能力控制。",
		Tags:     []string{"操作日志", "表单", "平台接口", "只读"},
		Request:  &FormReq{},
		Response: &FormResp{},
	},
}

func init() {
	packageContext.POST("form.form", Form, FormTemplate)
}

package operate_log

import (
	"encoding/json"
	"net/url"
	"strings"
)

func setQueryIfNotEmpty(query url.Values, key, value string) {
	value = strings.TrimSpace(value)
	if value != "" {
		query.Set(key, value)
	}
}

func normalizePositive(value, fallback int) int {
	if value <= 0 {
		return fallback
	}
	return value
}

func normalizeRange(value, fallback, min, max int) int {
	if value <= 0 {
		value = fallback
	}
	if value < min {
		return min
	}
	if value > max {
		return max
	}
	return value
}

func marshalPretty(v interface{}) (string, error) {
	data, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		return "", err
	}
	return string(data), nil
}

