package scheduled_agent_task

import (
	"fmt"
	"net/http"

	"github.com/ai-agent-os/ai-agent-os/dto"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/app"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/response"
)

type TaskActionReq struct {
	TaskID int64 `json:"task_id" widget:"name:任务 ID;type:number;min:1" validate:"required,min=1"`
}

type TaskActionResp struct {
	TaskID  int64  `json:"task_id" widget:"name:任务 ID;type:number"`
	Message string `json:"message" widget:"name:结果;type:text_area"`
}

type RunNowResp struct {
	TaskID           int64  `json:"task_id" widget:"name:任务 ID;type:number"`
	TimerTaskID      int64  `json:"timer_task_id" widget:"name:底层定时任务 ID;type:number"`
	TimerExecutionID int64  `json:"timer_execution_id" widget:"name:底层执行记录 ID;type:number"`
	Status           string `json:"status" widget:"name:状态;type:input"`
	ScheduledAt      string `json:"scheduled_at" widget:"name:计划执行时间;type:input"`
	Message          string `json:"message" widget:"name:结果;type:text_area"`
}

func Cancel(ctx *app.Context, resp response.Response) error {
	return taskAction(ctx, resp, http.MethodDelete, "", "已取消/删除智能体定时任务")
}

func Pause(ctx *app.Context, resp response.Response) error {
	return taskAction(ctx, resp, http.MethodPost, "pause", "已暂停智能体定时任务")
}

func Resume(ctx *app.Context, resp response.Response) error {
	return taskAction(ctx, resp, http.MethodPost, "resume", "已恢复智能体定时任务")
}

func taskAction(ctx *app.Context, resp response.Response, method string, action string, message string) error {
	var req TaskActionReq
	if err := ctx.ShouldBindValidate(&req); err != nil {
		return err
	}

	path := fmt.Sprintf("/agent/api/v1/scheduled_agent_tasks/%d", req.TaskID)
	if action != "" {
		path += "/" + action
	}
	if err := ctx.APICall(method, path, map[string]interface{}{}, nil); err != nil {
		return fmt.Errorf("[系统错误]-[ScheduledAgentTaskAction] 操作智能体定时任务失败, task_id: %d, action: %s, err: %w", req.TaskID, action, err)
	}
	return resp.Form(&TaskActionResp{
		TaskID:  req.TaskID,
		Message: fmt.Sprintf("%s #%d。", message, req.TaskID),
	}).Build()
}

func RunNow(ctx *app.Context, resp response.Response) error {
	var req TaskActionReq
	if err := ctx.ShouldBindValidate(&req); err != nil {
		return err
	}

	var result dto.ScheduledAgentRunNowResp
	path := fmt.Sprintf("/agent/api/v1/scheduled_agent_tasks/%d/run", req.TaskID)
	if err := ctx.APICall(http.MethodPost, path, map[string]interface{}{}, &result); err != nil {
		return fmt.Errorf("[系统错误]-[ScheduledAgentTaskRunNow] 立即运行智能体定时任务失败, task_id: %d, err: %w", req.TaskID, err)
	}
	return resp.Form(&RunNowResp{
		TaskID:           result.TaskID,
		TimerTaskID:      result.TimerTaskID,
		TimerExecutionID: result.TimerExecutionID,
		Status:           result.Status,
		ScheduledAt:      formatTime(result.ScheduledAt),
		Message:          fmt.Sprintf("已提交智能体定时任务 #%d 立即运行，可稍后查询执行记录。", req.TaskID),
	}).Build()
}

var CancelTemplate = &app.FormTemplate{
	BaseConfig: app.BaseConfig{
		Name:     "取消智能体定时任务",
		Desc:     "取消并删除当前用户有权限操作的智能体定时任务。该操作有副作用，执行前需用户明确确认。",
		Tags:     []string{"智能体定时任务", "取消", "删除", "平台接口", "副作用"},
		Request:  &TaskActionReq{},
		Response: &TaskActionResp{},
	},
}

var PauseTemplate = &app.FormTemplate{
	BaseConfig: app.BaseConfig{
		Name:     "暂停智能体定时任务",
		Desc:     "暂停当前用户有权限操作的智能体定时任务。暂停后不会继续按调度触发。",
		Tags:     []string{"智能体定时任务", "暂停", "平台接口", "副作用"},
		Request:  &TaskActionReq{},
		Response: &TaskActionResp{},
	},
}

var ResumeTemplate = &app.FormTemplate{
	BaseConfig: app.BaseConfig{
		Name:     "恢复智能体定时任务",
		Desc:     "恢复已暂停的智能体定时任务，并重新计算下次执行时间。",
		Tags:     []string{"智能体定时任务", "恢复", "平台接口", "副作用"},
		Request:  &TaskActionReq{},
		Response: &TaskActionResp{},
	},
}

var RunNowTemplate = &app.FormTemplate{
	BaseConfig: app.BaseConfig{
		Name:     "立即运行智能体定时任务",
		Desc:     "立即触发某个智能体定时任务执行一次。该操作异步提交，可随后查询执行记录获取会话 ID 和结果。",
		Tags:     []string{"智能体定时任务", "立即运行", "平台接口", "副作用"},
		Request:  &TaskActionReq{},
		Response: &RunNowResp{},
	},
}

func init() {
	packageContext.POST("cancel.form", Cancel, CancelTemplate)
	packageContext.POST("pause.form", Pause, PauseTemplate)
	packageContext.POST("resume.form", Resume, ResumeTemplate)
	packageContext.POST("run_now.form", RunNow, RunNowTemplate)
}

package scheduled_agent_task

import (
	"fmt"
	"net/http"
	"strings"

	"github.com/ai-agent-os/ai-agent-os/dto"
