type CreateReq struct {
	Name              string `json:"name" widget:"name:任务名称;type:input" validate:"required,min=1,max=200"`
	FullCodePath      string `json:"full_code_path" widget:"name:工作台目录完整路径;type:input;placeholder:/user/app/path" validate:"required"`
