type CreateResp struct {
	TaskID       int64  `json:"task_id" widget:"name:任务 ID;type:number"`
	TimerTaskID  int64  `json:"timer_task_id" widget:"name:底层定时任务 ID;type:number"`
	Name         string `json:"name" widget:"name:任务名称;type:input"`
	Status       string `json:"status" widget:"name:状态;type:input"`
	NextRunAt    string `json:"next_run_at" widget:"name:下次执行时间;type:input"`
	ScheduleType string `json:"schedule_type" widget:"name:调度类型;type:input"`
	FullCodePath string `json:"full_code_path" widget:"name:工作台目录完整路径;type:input"`
	Summary      string `json:"summary" widget:"name:创建结果;type:text_area"`
	TaskJSON     string `json:"task_json" widget:"name:任务 JSON;type:text_area"`
}

func Create(ctx *app.Context, resp response.Response) error {
	var req CreateReq
	if err := ctx.ShouldBindValidate(&req); err != nil {
		return err
	}

	scheduleType := strings.ToLower(strings.TrimSpace(req.ScheduleType))
	switch scheduleType {
	case "atime":
		if strings.TrimSpace(req.RunAt) == "" {
			return fmt.Errorf("schedule_type=atime 时必须填写 run_at")
		}
	case "cron":
		if strings.TrimSpace(req.CronExpr) == "" {
			return fmt.Errorf("schedule_type=cron 时必须填写 cron_expr")
		}
	case "every":
		if req.IntervalSeconds <= 0 {
			return fmt.Errorf("schedule_type=every 时 interval_seconds 必须大于 0")
		}
	default:
		return fmt.Errorf("schedule_type 必须是 atime/cron/every")
	}

	contextPolicy, err := optionalJSONObject("context_policy", req.ContextPolicy)
	if err != nil {
		return err
	}
	toolPolicy, err := optionalJSONObject("tool_policy", req.ToolPolicy)
	if err != nil {
		return err
	}
	approvalPolicy, err := optionalJSONObject("approval_policy", req.ApprovalPolicy)
	if err != nil {
		return err
	}
	budgetPolicy, err := optionalJSONObject("budget_policy", req.BudgetPolicy)
	if err != nil {
		return err
	}

	apiReq := &dto.CreateScheduledAgentTaskReq{
		Name:              strings.TrimSpace(req.Name),
		FullCodePath:      strings.TrimSpace(req.FullCodePath),
		Goal:              strings.TrimSpace(req.Goal),
		ModeCode:          strings.TrimSpace(req.ModeCode),
		Files:             strings.TrimSpace(req.Files),
		LLMConfigID:       req.LLMConfigID,
		ContextPolicy:     contextPolicy,
		ToolPolicy:        toolPolicy,
		ApprovalPolicy:    approvalPolicy,
		BudgetPolicy:      budgetPolicy,
		ScheduleType:      scheduleType,
		RunAt:             strings.TrimSpace(req.RunAt),
		CronExpr:          strings.TrimSpace(req.CronExpr),
		IntervalSeconds:   req.IntervalSeconds,
		MaxRuns:           req.MaxRuns,
		Timezone:          strings.TrimSpace(req.Timezone),
		RequestUser:       strings.TrimSpace(req.RequestUser),
		RequestUserDept:   strings.TrimSpace(req.RequestUserDept),
		NotifyUsers:       splitCSV(req.NotifyUsers),
		NotifyDepartments: splitCSV(req.NotifyDepartments),
		NotifyOn:          strings.TrimSpace(req.NotifyOn),
	}

	var item dto.ScheduledAgentTaskItem
	if err := ctx.APICall(http.MethodPost, "/agent/api/v1/scheduled_agent_tasks", apiReq, &item); err != nil {
		return fmt.Errorf("[系统错误]-[ScheduledAgentTaskCreate] 创建智能体定时任务失败, req: %+v, err: %w", req, err)
	}

	taskJSON, err := marshalPretty(item)
	if err != nil {
		return fmt.Errorf("[系统错误]-[ScheduledAgentTaskCreate] 序列化任务结果失败: %w", err)
	}

	return resp.Form(&CreateResp{
		TaskID:       item.ID,
		TimerTaskID:  item.TimerTaskID,
		Name:         item.Name,
		Status:       item.Status,
		NextRunAt:    formatTimePtr(item.NextRunAt),
		ScheduleType: item.ScheduleType,
		FullCodePath: item.FullCodePath,
		Summary:      formatCreateSummary(&item),
		TaskJSON:     taskJSON,
	}).Build()
}

func formatCreateSummary(item *dto.ScheduledAgentTaskItem) string {
	if item == nil {
		return "智能体定时任务已创建。"
	}
	lines := []string{
		fmt.Sprintf("智能体定时任务已创建：%s", item.Name),
		fmt.Sprintf("ID: %d", item.ID),
		fmt.Sprintf("工作台: %s", item.FullCodePath),
		fmt.Sprintf("调度: %s", item.ScheduleType),
		fmt.Sprintf("状态: %s", item.Status),
	}
	if item.TimerTaskID > 0 {
		lines = append(lines, fmt.Sprintf("底层定时任务 ID: %d", item.TimerTaskID))
	}
	if nextRunAt := formatTimePtr(item.NextRunAt); nextRunAt != "" {
		lines = append(lines, "下次执行: "+nextRunAt)
	}
	if runAt := formatTime(item.RunAt); runAt != "" {
		lines = append(lines, "首次执行: "+runAt)
	}
	return strings.Join(lines, "\n")
}

