		Name:     "创建智能体定时任务",
		Desc:     "创建到点后自动拉起智能体工作台会话的定时任务。支持 atime/cron/every 调度；目标是定时执行函数时应使用 scheduled_task。",
		Tags:     []string{"智能体定时任务", "创建", "平台接口", "调度", "副作用"},
		Request:  &CreateReq{},
		Response: &CreateResp{},
	},
}

