	if err != nil {
		return fmt.Errorf("[系统错误]-[ScheduledTaskCreate] 序列化任务结果失败: %w", err)
	}
	nextRunAt := ""
	if item.NextRunAt != nil {
		nextRunAt = *item.NextRunAt
	}
	return resp.Form(&CreateResp{
		TaskID:    item.ID,
		Name:      item.Name,
		Status:    item.Status,
		NextRunAt: nextRunAt,
		Summary:   fmt.Sprintf("定时任务已创建：%s\nID: %d\n目标: %s\n调度: %s\n状态: %s", item.Name, item.ID, item.FullCodePath, item.ScheduleType, item.Status),
