import (
	"encoding/json"
	"fmt"
	"net/url"
	"strconv"
	"strings"
	"time"

	"github.com/ai-agent-os/ai-agent-os/dto"
)

type scheduledAgentTaskListResp struct {
	List  []dto.ScheduledAgentTaskItem `json:"list"`
	Total int64                        `json:"total"`
}

type scheduledAgentExecutionListResp struct {
	List  []dto.ScheduledAgentExecutionItem `json:"list"`
	Total int64                             `json:"total"`
}

func splitCSV(raw string) []string {
	parts := strings.Split(raw, ",")
	out := make([]string, 0, len(parts))
	seen := map[string]struct{}{}
	for _, part := range parts {
		value := strings.TrimSpace(part)
		if value == "" {
			continue
		}
		if _, ok := seen[value]; ok {
			continue
		}
		seen[value] = struct{}{}
		out = append(out, value)
	}
	return out
}

func optionalJSONObject(name string, raw string) (json.RawMessage, error) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return nil, nil
	}
	var decoded interface{}
	if err := json.Unmarshal([]byte(raw), &decoded); err != nil {
		return nil, fmt.Errorf("%s 必须是合法 JSON 对象字符串: %w", name, err)
	}
	if _, ok := decoded.(map[string]interface{}); !ok {
		return nil, fmt.Errorf("%s 必须是 JSON 对象", name)
	}
	data, err := json.Marshal(decoded)
	if err != nil {
		return nil, err
	}
	return json.RawMessage(data), nil
}

func marshalPretty(v interface{}) (string, error) {
	data, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func normalizePositive(value, fallback int) int {
	if value <= 0 {
		return fallback
	}
	return value
}

func normalizeRange(value, fallback, min, max int) int {
	if value <= 0 {
		value = fallback
	}
	if value < min {
		return min
	}
	if value > max {
		return max
	}
	return value
}

func setQueryIfNotEmpty(query url.Values, key, value string) {
	value = strings.TrimSpace(value)
	if value != "" {
		query.Set(key, value)
	}
}

func setPagination(query url.Values, page, pageSize int) {
	query.Set("page", strconv.Itoa(normalizePositive(page, 1)))
	query.Set("page_size", strconv.Itoa(normalizeRange(pageSize, 20, 1, 100)))
}

func optionalInt64(enabled bool, value int64) *int64 {
	if !enabled {
		return nil
	}
	v := value
	return &v
}

func optionalInt(enabled bool, value int) *int {
	if !enabled {
		return nil
	}
	v := value
	return &v
}

func optionalStringPtr(enabled bool, value string) *string {
	if !enabled {
		return nil
	}
	v := strings.TrimSpace(value)
	return &v
}

func formatTime(value time.Time) string {
	if value.IsZero() {
		return ""
	}
	return value.Format("2006-01-02 15:04:05")
}

func formatTimePtr(value *time.Time) string {
	if value == nil {
		return ""
	}
	return formatTime(*value)
}

func formatTaskSummary(prefix string, item *dto.ScheduledAgentTaskItem) string {
	if item == nil {
		return prefix
	}
	lines := []string{
		fmt.Sprintf("%s：%s", prefix, item.Name),
		fmt.Sprintf("ID: %d", item.ID),
		fmt.Sprintf("工作台: %s", item.FullCodePath),
		fmt.Sprintf("调度: %s", item.ScheduleType),
		fmt.Sprintf("状态: %s", item.Status),
	}
	if item.TimerTaskID > 0 {
		lines = append(lines, fmt.Sprintf("底层定时任务 ID: %d", item.TimerTaskID))
	}
	if nextRunAt := formatTimePtr(item.NextRunAt); nextRunAt != "" {
		lines = append(lines, "下次执行: "+nextRunAt)
	}
	if runAt := formatTime(item.RunAt); runAt != "" {
		lines = append(lines, "首次执行: "+runAt)
	}
	if item.LastSessionID != "" {
		lines = append(lines, "最近会话: "+item.LastSessionID)
	}
	if item.LastErrorMessage != "" {
		lines = append(lines, "最近错误: "+item.LastErrorMessage)
	}
	return strings.Join(lines, "\n")
}

func formatTaskListSummary(result *scheduledAgentTaskListResp) string {
	if result == nil {
		return "未返回智能体定时任务列表。"
	}
	lines := []string{fmt.Sprintf("共 %d 个智能体定时任务。", result.Total)}
	for i, item := range result.List {
		line := fmt.Sprintf("%d. #%d %s [%s] %s", i+1, item.ID, item.Name, item.Status, item.FullCodePath)
		if nextRunAt := formatTimePtr(item.NextRunAt); nextRunAt != "" {
			line += "\n   下次执行: " + nextRunAt
		}
		if item.LastSessionID != "" {
			line += "\n   最近会话: " + item.LastSessionID
		}
		lines = append(lines, line)
	}
	return strings.Join(lines, "\n")
}

func formatExecutionListSummary(taskID int64, result *scheduledAgentExecutionListResp) string {
	if result == nil {
		return fmt.Sprintf("任务 #%d 未返回执行记录。", taskID)
	}
	lines := []string{fmt.Sprintf("任务 #%d 共 %d 条执行记录。", taskID, result.Total)}
	for i, item := range result.List {
		line := fmt.Sprintf("%d. #%d [%s] %s", i+1, item.ID, item.Status, formatTime(item.ScheduledAt))
		if item.SessionID != "" {
			line += "\n   会话: " + item.SessionID
		}
		if item.DurationMillis > 0 {
			line += fmt.Sprintf("\n   耗时: %dms", item.DurationMillis)
		}
		if strings.TrimSpace(item.ErrorMessage) != "" {
			line += "\n   错误: " + item.ErrorMessage
		}
		lines = append(lines, line)
	}
	return strings.Join(lines, "\n")
}

