type CreateReq struct {
	Name              string `json:"name" widget:"name:任务名称;type:input" validate:"required,min=1,max=200"`
	FullCodePath      string `json:"full_code_path" widget:"name:目标函数完整路径;type:input;placeholder:/user/app/path/function.form" validate:"required"`
	Action            string `json:"action" widget:"name:任务动作;type:select;options:execute,table_create,table_update,table_delete;render_default:execute"`
	Method            string `json:"method" widget:"name:请求方法;type:select;options:GET,POST,PUT,DELETE;placeholder:不填则按动作自动推导"`
	Payload           string `json:"payload" widget:"name:请求参数 JSON;type:text_area;placeholder:{}"`
	ScheduleType      string `json:"schedule_type" widget:"name:调度类型;type:select;options:atime,cron,every;render_default:atime" validate:"required"`
	RunAt             string `json:"run_at" widget:"name:执行时间;type:datetime;format:YYYY-MM-DD HH:mm:ss"`
	CronExpr          string `json:"cron_expr" widget:"name:Cron 表达式;type:input;placeholder:例如 0 9 * * *"`
	IntervalSeconds   int64  `json:"interval_seconds" widget:"name:间隔秒数;type:number;min:0"`
	MaxRuns           int    `json:"max_runs" widget:"name:最多执行次数;type:number;min:0"`
	Timezone          string `json:"timezone" widget:"name:时区;type:input;placeholder:默认使用服务端时区，如 Asia/Shanghai"`
	NotifyUsers       string `json:"notify_users" widget:"name:通知用户;type:users"`
	NotifyDepartments string `json:"notify_departments" widget:"name:通知部门;type:departments"`
	NotifyOn          string `json:"notify_on" widget:"name:通知条件;type:select;options:none,all,success,failed;render_default:none"`
}

type CreateResp struct {
	TaskID    int64  `json:"task_id" widget:"name:任务 ID;type:number"`
	Name      string `json:"name" widget:"name:任务名称;type:input"`
	Status    string `json:"status" widget:"name:状态;type:input"`
	NextRunAt string `json:"next_run_at" widget:"name:下次执行时间;type:input"`
	Summary   string `json:"summary" widget:"name:创建结果;type:text_area"`
	TaskJSON  string `json:"task_json" widget:"name:任务 JSON;type:text_area"`
}

func Create(ctx *app.Context, resp response.Response) error {
	var req CreateReq
	if err := ctx.ShouldBindValidate(&req); err != nil {
		return err
	}
	if strings.TrimSpace(req.ScheduleType) == "atime" && strings.TrimSpace(req.RunAt) == "" {
		return fmt.Errorf("schedule_type=atime 时必须填写 run_at")
	}

	payload, err := compactPayload(req.Payload)
	if err != nil {
		return fmt.Errorf("payload 必须是合法 JSON 对象字符串: %w", err)
	}

	action := strings.TrimSpace(req.Action)
	if action == "" {
		action = "execute"
	}
	method := strings.ToUpper(strings.TrimSpace(req.Method))
	if method == "" {
		method = methodForAction(action)
	}

	apiReq := &dto.CreateScheduledTaskReq{
		Name:              strings.TrimSpace(req.Name),
		FullCodePath:      strings.TrimSpace(req.FullCodePath),
		Action:            action,
		Method:            method,
		Payload:           payload,
		ScheduleType:      strings.TrimSpace(req.ScheduleType),
		RunAt:             strings.TrimSpace(req.RunAt),
		CronExpr:          strings.TrimSpace(req.CronExpr),
		IntervalSeconds:   req.IntervalSeconds,
		MaxRuns:           req.MaxRuns,
		Timezone:          strings.TrimSpace(req.Timezone),
		NotifyUsers:       splitCSV(req.NotifyUsers),
		NotifyDepartments: splitCSV(req.NotifyDepartments),
		NotifyOn:          strings.TrimSpace(req.NotifyOn),
	}

	var item dto.ScheduledTaskItem
	if err := ctx.APICall(http.MethodPost, "/workspace/api/v1/scheduled_tasks", apiReq, &item); err != nil {
		return fmt.Errorf("[系统错误]-[ScheduledTaskCreate] 创建定时任务失败, req: %+v, err: %w", req, err)
	}

	taskJSON, err := marshalPretty(item)
	if err != nil {
		return fmt.Errorf("[系统错误]-[ScheduledTaskCreate] 序列化任务结果失败: %w", err)
	}
	nextRunAt := ""
	if item.NextRunAt != nil {
		nextRunAt = *item.NextRunAt
	}
	return resp.Form(&CreateResp{
		TaskID:    item.ID,
		Name:      item.Name,
		Status:    item.Status,
		NextRunAt: nextRunAt,
		Summary:   fmt.Sprintf("定时任务已创建：%s\nID: %d\n目标: %s\n调度: %s\n状态: %s", item.Name, item.ID, item.FullCodePath, item.ScheduleType, item.Status),
		TaskJSON:  taskJSON,
	}).Build()
}

