func formatExecutionSummary(taskID int64, result *dto.ListScheduledTaskExecutionsResp) string {
	if result == nil {
		return fmt.Sprintf("任务 #%d 未返回执行记录。", taskID)
	}
	lines := []string{fmt.Sprintf("任务 #%d 共 %d 条执行记录。", taskID, result.Total)}
	for i, item := range result.List {
		line := fmt.Sprintf("%d. #%d [%s] %s", i+1, item.ID, item.Status, item.ExecutedAt)
		if item.DurationMillis > 0 {
			line += fmt.Sprintf("，耗时 %dms", item.DurationMillis)
		}
		if strings.TrimSpace(item.ErrorMessage) != "" {
			line += "\n   错误: " + item.ErrorMessage
		}
		lines = append(lines, line)
	}
	return strings.Join(lines, "\n")
}

package scheduled_task

import (
	"encoding/json"
	"fmt"
	"strings"
)

func normalizePositive(value, fallback int) int {
	if value <= 0 {
		return fallback
	}
	return value
}

func normalizeRange(value, fallback, min, max int) int {
	if value <= 0 {
		value = fallback
	}
	if value < min {
		return min
	}
	if value > max {
		return max
	}
	return value
}

func splitCSV(raw string) []string {
	parts := strings.Split(raw, ",")
	out := make([]string, 0, len(parts))
	seen := map[string]struct{}{}
	for _, part := range parts {
		value := strings.TrimSpace(part)
		if value == "" {
			continue
		}
		if _, ok := seen[value]; ok {
			continue
		}
		seen[value] = struct{}{}
		out = append(out, value)
	}
	return out
}

func compactPayload(raw string) (json.RawMessage, error) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		raw = "{}"
	}
	var decoded interface{}
	if err := json.Unmarshal([]byte(raw), &decoded); err != nil {
		return nil, err
	}
	if _, ok := decoded.(map[string]interface{}); !ok {
		return nil, fmt.Errorf("payload 必须是 JSON 对象")
	}
	data, err := json.Marshal(decoded)
	if err != nil {
		return nil, err
	}
	return json.RawMessage(data), nil
}

func marshalPretty(v interface{}) (string, error) {
	data, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func methodForAction(action string) string {
	switch strings.ToLower(strings.TrimSpace(action)) {
	case "table_update":
		return "PUT"
	case "table_delete":
		return "DELETE"
	default:
		return "POST"
	}
}

package scheduled_task

import (
	"fmt"
	"net/http"
	"net/url"
	"strconv"
	"strings"

	"github.com/ai-agent-os/ai-agent-os/dto"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/app"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/response"
)

type ListReq struct {
	FullCodePath string `json:"full_code_path" widget:"name:路径前缀;type:input;placeholder:可选，查询该路径及子路径下的任务"`
	Status       string `json:"status" widget:"name:任务状态;type:select;options:pending,done,failed,cancelled"`
	Page         int    `json:"page" widget:"name:页码;type:number;min:1;render_default:1"`
	PageSize     int    `json:"page_size" widget:"name:每页数量;type:number;min:1;max:100;render_default:20"`
}

type ListResp struct {
	Total     int64  `json:"total" widget:"name:总数;type:number"`
	Summary   string `json:"summary" widget:"name:摘要;type:text_area"`
	TasksJSON string `json:"tasks_json" widget:"name:任务 JSON;type:text_area"`
}

func List(ctx *app.Context, resp response.Response) error {
	var req ListReq
	if err := ctx.ShouldBindValidate(&req); err != nil {
		return err
	}

	query := url.Values{}
	query.Set("page", strconv.Itoa(normalizePositive(req.Page, 1)))
	query.Set("page_size", strconv.Itoa(normalizeRange(req.PageSize, 20, 1, 100)))
	setQueryIfNotEmpty(query, "full_code_path", req.FullCodePath)
	setQueryIfNotEmpty(query, "status", req.Status)

	var result dto.ListScheduledTasksResp
	if err := ctx.APICall(http.MethodGet, "/workspace/api/v1/scheduled_tasks?"+query.Encode(), nil, &result); err != nil {
		return fmt.Errorf("[系统错误]-[ScheduledTaskList] 查询定时任务失败, req: %+v, err: %w", req, err)
	}

	tasksJSON, err := marshalPretty(result.List)
	if err != nil {
		return fmt.Errorf("[系统错误]-[ScheduledTaskList] 序列化任务列表失败: %w", err)
	}
	return resp.Form(&ListResp{
		Total:     result.Total,
		Summary:   formatTaskListSummary(&result),
		TasksJSON: tasksJSON,
	}).Build()
}

var ListTemplate = &app.FormTemplate{
	BaseConfig: app.BaseConfig{
		Name:     "查询定时任务",
		Desc:     "查询当前用户创建的定时任务列表。可按路径前缀和任务状态过滤。",
		Tags:     []string{"定时任务", "查询", "平台接口"},
		Request:  &ListReq{},
		Response: &ListResp{},
	},
}

func init() {
	packageContext.POST("list.form", List, ListTemplate)
}

func setQueryIfNotEmpty(query url.Values, key, value string) {
	value = strings.TrimSpace(value)
	if value != "" {
		query.Set(key, value)
	}
}

func formatTaskListSummary(result *dto.ListScheduledTasksResp) string {
	if result == nil {
		return "未返回定时任务列表"
	}
	lines := []string{fmt.Sprintf("共 %d 个定时任务。", result.Total)}
	for i, item := range result.List {
		line := fmt.Sprintf("%d. #%d %s [%s] %s", i+1, item.ID, item.Name, item.Status, item.FullCodePath)
		if item.NextRunAt != nil && *item.NextRunAt != "" {
			line += "\n   下次执行: " + *item.NextRunAt
		}
		lines = append(lines, line)
	}
	return strings.Join(lines, "\n")
}
